import Foundation
import SQLite3
@testable import OMPGUI

@main private enum BrowserCookieImportChecks {
    // Independent Node.js crypto vectors, not ciphertext generated by production code.
    static let session = "7631302d382dfc0896f846c6114f019207de2c3d4e269b8ae0be9473025f43bc98ce4a840cdb8478559e2c63ac9665fc9f59ff"
    static let partition = "76313075b6e195016b0155464d6b4ab5f88716bc73da0cb6c3bbc2c7aa86bf7850ede9770fc73b40733d7be7aa0da40c6f139a"
    static let empty = "7631302d382dfc0896f846c6114f019207de2c3d4e269b8ae0be9473025f43bc98ce4acde93d6a5efbf0c7a0f8cdbda70afc8f"
    static let legacy = "7631303dfb2c2a59fc8ca755f42c33a6d4b966"
    static let wrongHost = "76313041c860f69703228e1f85386db9c7489ebdd9843bc704923dea3740a0613bd954c30ea2a1820fb6f5d2103579f31f245e"

    @MainActor static func main() async throws {
        guard let output = CaptureRun.outputDirectory else { fatalError("Isolated capture required") }
        let now = Date(timeIntervalSince1970: 2_000_000_000)
        let fixture = try CookieDatabase(root: output.appendingPathComponent("chrome"))
        defer { fixture.close() }
        var checks = 0
        func expect(_ value: Bool, _ message: String) { precondition(value, message); checks += 1 }
        func rejects(_ expected: BrowserCookieImportError, _ message: String, _ body: () throws -> Void) {
            do { try body(); fatalError(message) }
            catch let error as BrowserCookieImportError { expect(String(describing: error) == String(describing: expected), message) }
            catch { fatalError("Unexpected error: \(error)") }
        }
        let password = Data("fixture-safe-storage".utf8)
        let key = try ChromeCookieSource.deriveKey(password)
        expect(key == hex("db16859dab5511521615299fa064b832"), "macOS key derivation agrees with an independent PBKDF2 vector")
        expect(try ChromeCookieSource.decrypt(hex(session), key: key, host: "example.test", version: 24) == "session-value",
               "A v24 cookie decrypts and verifies the entire domain digest")
        expect(try ChromeCookieSource.decrypt(hex(empty), key: key, host: "example.test", version: 24).isEmpty,
               "Encrypted empty values retain their valid domain digest")
        expect(try ChromeCookieSource.decrypt(hex(legacy), key: key, host: "example.test", version: 23) == "legacy-value",
               "Pre-v24 values do not lose their first 32 bytes")
        rejects(.decryptionFailed, "A valid CBC value bound to another host is rejected") {
            _ = try ChromeCookieSource.decrypt(hex(wrongHost), key: key, host: "example.test", version: 24)
        }
        rejects(.decryptionFailed, "A missing v24 digest is never treated as an old-format value") {
            _ = try ChromeCookieSource.decrypt(hex(legacy), key: key, host: "example.test", version: 24)
        }
        rejects(.decryptionFailed, "Padding and key errors cannot turn into an empty successful cookie") {
            _ = try ChromeCookieSource.decrypt(hex(session), key: Data(repeating: 0, count: 16), host: "example.test", version: 24)
        }
        rejects(.unsupportedEncryption, "Unknown ciphertext versions are refused") {
            _ = try ChromeCookieSource.decrypt(Data("v20unknown".utf8), key: key, host: "example.test", version: 24)
        }
        rejects(.keychainUnavailable, "Capture runs cannot touch the personal Keychain") { _ = try ChromeCookieSource.readKeychainPassword() }

        try fixture.put(name: "session", encrypted: session)
        let expiry = Int64((now.timeIntervalSince1970 + 300 + 11_644_473_600) * 1_000_000)
        try fixture.put(name: "partition", encrypted: partition, domain: ".example.test", top: "https://top.test", ancestor: 1, expiry: expiry)
        try fixture.put(name: "partition", encrypted: partition, domain: ".example.test", top: "https://top.test", ancestor: 0, expiry: expiry)
        try fixture.put(name: "partition", encrypted: partition, domain: ".example.test", top: "https://other.test", ancestor: 1, expiry: expiry)
        try fixture.put(name: "empty", encrypted: empty)
        try fixture.put(name: "expired", encrypted: "763939", expiry: 1)
        let profiles = try ChromeCookieSource.profiles(root: fixture.root)
        expect(profiles.count == 1 && profiles[0].name == "工作账号", "Discovery reads display labels without decrypting cookies")
        let profile = profiles[0]
        var keyReads = 0
        func read() throws -> BrowserCookieImport {
            try ChromeCookieSource.read(profile, now: now) { keyReads += 1; return password }
        }
        let before = try Data(contentsOf: fixture.file), wal = try Data(contentsOf: URL(fileURLWithPath: fixture.file.path + "-wal"))
        let imported = try read()
        expect(imported.cookies.count == 5 && imported.skippedCount == 1, "Committed WAL cookies are included and the expired row is counted once")
        expect(keyReads == 1, "One import reads the Keychain at most once")
        expect(try Data(contentsOf: fixture.file) == before && Data(contentsOf: URL(fileURLWithPath: fixture.file.path + "-wal")) == wal,
               "Source database and committed WAL bytes are not rewritten")
        expect(imported.cookies.first?.value == "session-value" && imported.cookies.first?.session == true,
               "Host-only HttpOnly session values survive native decoding")
        let partitions = imported.cookies.filter { $0.partitionKey != nil }
        expect(partitions.count == 3 && Set(partitions.map(\.identity)).count == 3,
               "Identical names, hosts and paths remain distinct across top-level sites and ancestor bits")
        expect(partitions.allSatisfy { $0.priority == "High" && $0.sourcePort == 443 && $0.sourceScheme == "Secure" },
               "Priority and source scheme/port are preserved")
        expect(partitions.allSatisfy { abs($0.expirationDate! - now.timeIntervalSince1970 - 300) < 0.001 },
               "WebKit int64 timestamps retain their epoch and precision")
        expect(imported.cookies[0].parameters["url"]?.string == "https://example.test:443/"
            && imported.cookies[0].parameters["domain"] == nil && imported.cookies[0].parameters["expires"] == nil,
               "CDP conversion preserves host-only scope and session lifetime")
        expect(partitions[0].parameters["domain"]?.string == ".example.test"
            && partitions[0].parameters["sameSite"]?.string == "None", "Domain-cookie scope and SameSite=None survive conversion")

        let frozen = try ChromeCookieSource.snapshot(fixture.file)
        try fixture.put(name: "later", encrypted: session)
        expect(try count(frozen) == 6, "The snapshot is independent of later committed source writes")
        sqlite3_close(frozen)
        try fixture.execute("BEGIN IMMEDIATE")
        try fixture.put(name: "uncommitted", encrypted: session)
        let stable = try read()
        expect(stable.cookies.count == 6 && !stable.cookies.contains(where: { $0.name == "uncommitted" }),
               "A live writer's uncommitted rows never enter the backup")
        try fixture.execute("ROLLBACK")
        try fixture.execute("DELETE FROM cookies WHERE name = 'later'")

        var actual = imported.cookies.map(actualCookie)
        expect(BrowserCookieImporter.retained(imported.cookies, in: actual), "Acknowledgement compares every imported cookie and its partition")
        var changed = actual[1].object!; changed["partitionKey"] = ["topLevelSite": "https://top.test", "hasCrossSiteAncestor": true]
        actual[2] = .object(changed)
        expect(!BrowserCookieImporter.retained(imported.cookies, in: actual), "A lost ancestor bit or collapsed partition cannot publish a profile")
        actual = imported.cookies.map(actualCookie)
        for (field, value) in [("value", JSONValue.string("wrong")), ("priority", .string("Low")),
                               ("sourcePort", .int(80)), ("secure", .bool(false)), ("sameSite", .string("Strict"))] {
            var item = actual[0].object!; item[field] = value
            var bad = actual; bad[0] = .object(item)
            expect(!BrowserCookieImporter.retained(imported.cookies, in: bad), "Target changes to \(field) are rejected")
        }
        expect(!BrowserCookieImporter.retained(imported.cookies, in: Array(actual.dropLast())), "Partial native writes cannot publish a profile")

        try fixture.execute("CREATE TABLE fixture_original AS SELECT * FROM cookies")
        func restoreCookies() throws {
            try fixture.execute("BEGIN; DELETE FROM cookies; INSERT INTO cookies SELECT * FROM fixture_original; UPDATE meta SET value = '24'; COMMIT")
        }
        for (sql, kept, skipped) in [
            ("UPDATE cookies SET encrypted_value = X'\(wrongHost)' WHERE name = 'session'", 4, 2),
            ("UPDATE cookies SET encrypted_value = X'763939' WHERE name = 'session'", 4, 2),
            ("UPDATE cookies SET value = 'plaintext' WHERE name = 'session'", 4, 2),
            ("UPDATE cookies SET has_cross_site_ancestor = 2 WHERE name = 'partition'", 2, 4),
            ("UPDATE cookies SET top_frame_site_key = 'https://top.test/path' WHERE name = 'partition'", 2, 4),
            ("UPDATE cookies SET is_secure = 0 WHERE name = 'partition'", 2, 4),
            ("UPDATE cookies SET samesite = 99 WHERE name = 'session'", 4, 2),
            ("UPDATE cookies SET path = 'relative' WHERE name = 'session'", 4, 2),
            ("UPDATE cookies SET value = CAST(X'ff' AS TEXT), encrypted_value = X'' WHERE name = 'session'", 4, 2),
            ("UPDATE cookies SET value = replace(hex(zeroblob(10000)), '0', 'x'), encrypted_value = X'' WHERE name = 'session'", 4, 2),
            ("UPDATE cookies SET has_expires = 1 WHERE name = 'session'", 4, 2),
            ("INSERT INTO cookies SELECT * FROM cookies WHERE name = 'session'", 5, 2)
        ] {
            try fixture.execute(sql)
            let partial = try read()
            expect(partial.cookies.count == kept && partial.skippedCount == skipped,
                   "Only the unusable rows are skipped; healthy cookies and counts survive")
            expect(partial.cookies.allSatisfy { $0.value == "session-value" || $0.value == "partition-value" || $0.value.isEmpty },
                   "Skipped rows cannot leak hash bytes or lossy values into the usable subset")
            try restoreCookies()
        }
        for (sql, error) in [
            ("UPDATE meta SET value = '25' WHERE key = 'version'", BrowserCookieImportError.unsupportedDatabase),
            ("UPDATE meta SET value = 'invalid' WHERE key = 'last_compatible_version'", .invalidDatabase),
            ("ALTER TABLE cookies RENAME COLUMN source_port TO unsupported_port", .invalidDatabase)
        ] {
            try fixture.execute(sql)
            rejects(error, "Structural schema failures still abort before reading a key") {
                _ = try ChromeCookieSource.read(profile, now: now) { fatalError("Invalid schema must not request the Keychain") }
            }
            if sql.hasPrefix("ALTER") { try fixture.execute("ALTER TABLE cookies RENAME COLUMN unsupported_port TO source_port") }
            try restoreCookies()
        }
        try fixture.execute("DELETE FROM cookies WHERE name != 'expired'")
        rejects(.noImportableCookies(1), "An entirely expired profile reports its skip count without adding a profile") {
            _ = try ChromeCookieSource.read(profile, now: now) { fatalError("Expired rows must not request the Keychain") }
        }
        try restoreCookies()
        try fixture.execute("UPDATE cookies SET encrypted_value = X'763939'")
        rejects(.noImportableCookies(6), "An entirely unsupported profile reports all skipped rows") {
            _ = try ChromeCookieSource.read(profile, now: now) { fatalError("Unknown ciphertext must not request the Keychain") }
        }
        try restoreCookies()
        rejects(.noImportableCookies(6), "A bad decryption key never creates an empty successful profile") {
            _ = try ChromeCookieSource.read(profile, now: now) { Data("wrong-key".utf8) }
        }
        rejects(.keychainDenied, "Keychain denial aborts without a fallback key") {
            _ = try ChromeCookieSource.read(profile, now: now) { throw BrowserCookieImportError.keychainDenied }
        }
        let escaped = ChromeCookieProfile(root: fixture.root, directoryName: "../Default", name: "Escape")
        rejects(.invalidDatabase, "Source profile identifiers cannot traverse directories") {
            _ = try ChromeCookieSource.read(escaped, keyProvider: { fatalError("Unsafe paths cannot request the Keychain") })
        }
        let symlink = fixture.root.appendingPathComponent("Profile 2", isDirectory: true)
        try FileManager.default.createSymbolicLink(at: symlink, withDestinationURL: fixture.file.deletingLastPathComponent())
        rejects(.invalidDatabase, "Symlink profiles are rejected instead of reading another directory") { _ = try ChromeCookieSource.profiles(root: fixture.root) }
        try FileManager.default.removeItem(at: symlink)
        let sidecar = URL(fileURLWithPath: fixture.file.path + "-shm")
        let moved = sidecar.appendingPathExtension("owned")
        try FileManager.default.moveItem(at: sidecar, to: moved)
        try FileManager.default.createSymbolicLink(at: sidecar, withDestinationURL: moved)
        rejects(.invalidDatabase, "A symlink WAL index is rejected before SQLite opens it") { _ = try read() }
        try FileManager.default.removeItem(at: sidecar)
        try FileManager.default.moveItem(at: moved, to: sidecar)

        let mixedTarget = CookieTarget(imported.cookies, rejected: ["session"])
        let copied = try await BrowserCookieImporter.copyCookies(imported, call: mixedTarget.call)
        expect(copied.cookies.count == 4 && copied.skippedCount == 2, "Native field rejection isolates one cookie without discarding the remaining batch")
        expect(mixedTarget.writeSizes.contains(1) && mixedTarget.clearCount == 0,
               "Only rejected batches are split; valid native storage is not cleared")
        expect(copied.cookies.filter { $0.partitionKey != nil }.count == 3,
               "All supported native partition identities remain distinct during partial import")

        let changedTarget = CookieTarget(imported.cookies, changed: ["empty"])
        let verified = try await BrowserCookieImporter.copyCookies(imported, call: changedTarget.call)
        expect(verified.cookies.count == 4 && verified.skippedCount == 2 && changedTarget.clearCount == 1,
               "A silently changed cookie is skipped and removed from the new target context")
        expect(BrowserCookieImporter.retained(verified.cookies, in: Array(changedTarget.stored.values)),
               "Only exactly verified values and metadata remain after rebuilding the fresh target")

        let droppedTarget = CookieTarget(imported.cookies, dropped: ["empty"])
        let dropped = try await BrowserCookieImporter.copyCookies(imported, call: droppedTarget.call)
        expect(dropped.cookies.count == 4 && dropped.skippedCount == 2 && droppedTarget.clearCount == 0,
               "Silent native refusal contributes one skip without unnecessary replay")

        let failedTarget = CookieTarget(imported.cookies)
        failedTarget.failWrites = true
        do { _ = try await BrowserCookieImporter.copyCookies(imported, call: failedTarget.call); fatalError("Transport failure must abort") }
        catch let error as BrowserCookieImportError {
            expect(error == .unavailable && failedTarget.writeSizes.count == 1 && failedTarget.clearCount == 0,
                   "Transport failures do not trigger cookie retries or partial success")
        }
        let unreadableTarget = CookieTarget(imported.cookies)
        unreadableTarget.failReadAfterWrite = true
        do { _ = try await BrowserCookieImporter.copyCookies(imported, call: unreadableTarget.call); fatalError("Verification read failure must abort") }
        catch { expect(error is BrowserCookieImportError && unreadableTarget.clearCount == 0, "Native read failures cannot be mislabeled as skipped cookies") }
        let occupiedTarget = CookieTarget(imported.cookies)
        occupiedTarget.stored["existing"] = actualCookie(imported.cookies[0])
        do { _ = try await BrowserCookieImporter.copyCookies(imported, call: occupiedTarget.call); fatalError("Target must be fresh") }
        catch {
            expect(occupiedTarget.writeSizes.isEmpty && occupiedTarget.clearCount == 0 && occupiedTarget.stored.count == 1,
                   "An occupied target is never cleared or overwritten")
        }
        let rejectedTarget = CookieTarget(imported.cookies, rejected: Set(imported.cookies.map(\.name)))
        do { _ = try await BrowserCookieImporter.copyCookies(imported, call: rejectedTarget.call); fatalError("No target cookies were accepted") }
        catch let error as BrowserCookieImportError {
            expect(error == .noImportableCookies(6), "Complete native rejection reports the combined skip count and cannot publish a profile")
        }
        expect(BrowserCookieWriteError.isCookieRejection(method: "Network.setCookies", error: ["code": -32602])
            && !BrowserCookieWriteError.isCookieRejection(method: "Network.getAllCookies", error: ["code": -32602])
            && !BrowserCookieWriteError.isCookieRejection(method: "Network.setCookies", error: ["code": -32603]),
               "Only explicit set-cookie parameter rejection is eligible for row isolation")

        let label = BrowserProfileRecord(id: UUID(), name: "Work")
        let summary = BrowserCookieImportResult(profile: label, cookieCount: 37, skippedCount: 11).message
        expect(summary.contains("37") && summary.contains("11") && !summary.contains("expired") && !summary.contains("过期"),
               "The result has a single skip count with no reason breakdown")
        let completeSummary = BrowserCookieImportResult(profile: label, cookieCount: 37, skippedCount: 0).message
        expect(!completeSummary.contains("Skipped") && !completeSummary.contains("跳过"), "No redundant skip message is added when nothing was skipped")

        var catalogue = BrowserProfileConfiguration()
        let manual = catalogue.add(named: " Work ")!
        expect(catalogue.add(named: "work") == nil, "Manual profile names remain case-insensitively unique")
        let first = try catalogue.addChromeImport(id: UUID(), sourceName: "Work")
        let second = try catalogue.addChromeImport(id: UUID(), sourceName: "Work")
        expect(first.name == "Work [Chrome]" && second.name == "Work (2) [Chrome]" && first.id != manual.id,
               "Automatic imports use separate UUIDs and collision-safe names")
        let settings = AppSettings(), active = BrowserProfileConfiguration.activeProfile
        settings.browserProfiles = catalogue
        expect(AppSettings().browserProfiles == catalogue && BrowserProfileConfiguration.activeProfile == active,
               "Saved imported selection never switches the running profile")
        do { _ = try await BrowserCookieImporter.shared.importChrome(profile, profileID: active.id); fatalError("Active target must be protected") }
        catch let error as BrowserCookieImportError { expect(error == .unavailable, "The active profile cannot be used as a partial-import staging target") }
        try fixture.execute("UPDATE meta SET value = '25' WHERE key = 'version'")
        do { _ = try await settings.importBrowserCookies(from: profile); fatalError("Future source should fail") }
        catch { expect(error is BrowserCookieImportError && settings.browserProfiles == catalogue, "A source failure leaves the saved catalogue unchanged") }
        let canceled = Task { @MainActor in try await settings.importBrowserCookies(from: profile) }
        canceled.cancel()
        do { _ = try await canceled.value; fatalError("Canceled import should fail") }
        catch is CancellationError { expect(settings.browserProfiles == catalogue, "Cancellation cannot add or select a profile") }
        expect(!BrowserCookieImporter.shared.isImporting && EmbeddedBrowserRuntime.shared.endpoint == nil,
               "Reader failure and cancellation drain without starting CEF")
        expect(!FileManager.default.fileExists(atPath: BrowserLocalization.resources.resourceURL!.appendingPathComponent("ChromeCookieExporter").path),
               "The app no longer bundles an exporter extension")
        let errors: [BrowserCookieImportError] = [.permissionDenied, .keychainDenied, .unsupportedEncryption, .decryptionFailed, .snapshotBusy]
        expect(errors.allSatisfy { !$0.localizedDescription.contains("fixture-safe-storage") && !$0.localizedDescription.contains("session-value") },
               "Diagnostics never disclose key or cookie values")
        print("Native Chrome Cookie import: \(checks) checks passed")
    }

    static func hex(_ value: String) -> Data {
        Data(stride(from: 0, to: value.count, by: 2).map { offset in
            let start = value.index(value.startIndex, offsetBy: offset)
            return UInt8(value[start..<value.index(start, offsetBy: 2)], radix: 16)!
        })
    }

    static func count(_ db: OpaquePointer) throws -> Int {
        var statement: OpaquePointer?
        guard sqlite3_prepare_v2(db, "SELECT count(*) FROM cookies", -1, &statement, nil) == SQLITE_OK,
              sqlite3_step(statement) == SQLITE_ROW else { fatalError("Fixture snapshot query failed") }
        defer { sqlite3_finalize(statement) }
        return Int(sqlite3_column_int64(statement, 0))
    }

    static func actualCookie(_ cookie: BrowserCookieImport.Cookie) -> JSONValue {
        var item = cookie.parameters.object!
        item.removeValue(forKey: "url")
        item["domain"] = .string(cookie.domain)
        item["session"] = .bool(cookie.session)
        return .object(item)
    }
}

private final class CookieDatabase {
    let root: URL
    let file: URL
    private var db: OpaquePointer?
    init(root: URL) throws {
        self.root = root
        file = root.appendingPathComponent("Default/Network/Cookies")
        try FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
        try Data(#"{"profile":{"info_cache":{"Default":{"name":"工作账号"}}}}"#.utf8).write(to: root.appendingPathComponent("Local State"))
        guard sqlite3_open(file.path, &db) == SQLITE_OK else { fatalError("Fixture SQLite open failed") }
        try execute("""
            PRAGMA journal_mode = WAL; PRAGMA wal_autocheckpoint = 0;
            CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT);
            INSERT INTO meta VALUES('version', '24'), ('last_compatible_version', '24');
            CREATE TABLE cookies(host_key TEXT, name TEXT, value TEXT, encrypted_value BLOB, path TEXT,
                is_secure INTEGER, is_httponly INTEGER, expires_utc INTEGER, is_persistent INTEGER, has_expires INTEGER,
                samesite INTEGER, priority INTEGER, source_scheme INTEGER, source_port INTEGER,
                top_frame_site_key TEXT, has_cross_site_ancestor INTEGER);
            """)
    }
    func put(name: String, encrypted: String, domain: String = "example.test", top: String = "", ancestor: Int = 1, expiry: Int64 = 0) throws {
        let persistent = expiry == 0 ? 0 : 1, sameSite = top.isEmpty ? 1 : 0
        try execute("INSERT INTO cookies VALUES('\(domain)', '\(name)', '', X'\(encrypted)', '/', 1, 1, \(expiry), \(persistent), \(persistent), \(sameSite), 2, 2, 443, '\(top)', \(ancestor))")
    }
    func execute(_ sql: String) throws {
        guard sqlite3_exec(db, sql, nil, nil, nil) == SQLITE_OK else { fatalError("Fixture SQLite statement failed") }
    }
    func close() { if let db { sqlite3_close(db); self.db = nil } }
    deinit { close() }
}

/// A deterministic page-context Cookie store; no browser process is launched.
@MainActor private final class CookieTarget {
    let originals: [JSONValue: BrowserCookieImport.Cookie]
    let rejected: Set<String>
    let changed: Set<String>
    let dropped: Set<String>
    var stored: [String: JSONValue] = [:]
    var writeSizes: [Int] = []
    var clearCount = 0
    var failWrites = false
    var failReadAfterWrite = false

    init(_ cookies: [BrowserCookieImport.Cookie], rejected: Set<String> = [], changed: Set<String> = [], dropped: Set<String> = []) {
        originals = Dictionary(uniqueKeysWithValues: cookies.map { ($0.parameters, $0) })
        self.rejected = rejected; self.changed = changed; self.dropped = dropped
    }

    func call(_ method: String, _ parameters: JSONValue) async throws -> JSONValue {
        switch method {
        case "Network.getAllCookies":
            if failReadAfterWrite && !writeSizes.isEmpty { throw BrowserCookieImportError.unavailable }
            return ["cookies": .array(Array(stored.values))]
        case "Network.setCookies":
            let batch = parameters["cookies"]!.array!
            writeSizes.append(batch.count)
            if failWrites { throw BrowserCookieImportError.unavailable }
            if batch.contains(where: { rejected.contains($0["name"]!.string!) }) { throw BrowserCookieWriteError.invalidCookie }
            for value in batch {
                let cookie = originals[value]!
                if dropped.contains(cookie.name) { continue }
                var actual = BrowserCookieImportChecks.actualCookie(cookie).object!
                if changed.contains(cookie.name) { actual["priority"] = .string("Low") }
                stored[cookie.identity] = .object(actual)
            }
            return [:]
        case "Network.clearBrowserCookies":
            clearCount += 1
            stored.removeAll()
            return [:]
        default:
            fatalError("Unexpected protocol command")
        }
    }
}
